function parseAge(text) {
  var age = Number(text);
  if (isNaN(age)) {
    throw new Error("Not a number: " + text);
  }
  return age;
}

try {
  console.log(parseAge("42"));
  console.log(parseAge("abc"));
} catch (e) {
  console.log("Caught: " + e.message);
} finally {
  console.log("done");
}
